// Query validation and sanitization
const query = $input.item.json.query;
const collection = $input.item.json.collection || 'default';

// Check if query exists
if (!query) {
  throw new Error('Query parameter is required');
}

// Sanitize query (remove excessive whitespace, etc.)
const sanitizedQuery = query.trim().replace(/\s+/g, ' ');

// Check query length
if (sanitizedQuery.length < 3) {
  throw new Error('Query is too short');
}

if (sanitizedQuery.length > 500) {
  throw new Error('Query is too long (max 500 characters)');
}

// Check for potential harmful content (basic check)
const potentiallyHarmful = /\b(rm -rf|drop table|delete from|;--|\bexec\b|\beval\b|<script>)/i.test(sanitizedQuery);
if (potentiallyHarmful) {
  throw new Error('Query contains potentially harmful content');
}

// Generate a query ID for tracking
const queryId = `query_${Date.now()}_${Math.random().toString(36).substring(2, 10)}`;

// Return sanitized query
return {
  json: {
    query_id: queryId,
    query: sanitizedQuery,
    collection: collection,
    timestamp: new Date().toISOString()
  }
};

// Cache checking function
async function getCachedResponse(items) {
  const item = items[0];
  const query = item.json.query;
  const collection = item.json.collection;

  // Generate cache key
  const cacheKey = `query_${collection}_${query.toLowerCase().replace(/\s+/g, '_')}`;

  // In a real implementation, this would check Redis
  // For this template, we'll simulate a cache check
  const cacheHit = false;

  if (cacheHit) {
    // Return cached response
    return [
      {
        json: {
          ...item.json,
          cached: true,
          context: ['Cached context 1', 'Cached context 2'],
          response: 'This is a cached response',
          confidence_score: 0.95,
          processing_time: 0.05
        }
      }
    ];
  } else {
    // No cache hit, continue processing
    return items;
  }
}

// Context ranking and optimization
const searchResults = $input.item.json;
const query = $input.item.json.query;

// Extract results from ChromaDB response
let results = [];

if (searchResults.ids && searchResults.ids[0]) {
  // Process each result
  for (let i = 0; i < searchResults.ids[0].length; i++) {
    results.push({
      id: searchResults.ids[0][i],
      content: searchResults.documents[0][i],
      metadata: searchResults.metadatas[0][i],
      distance: searchResults.distances[0][i],
      similarity: 1.0 - Math.min(searchResults.distances[0][i], 1.0)
    });
  }
}

// Re-rank results based on multiple factors
results = results.map(result => {
  // Calculate keyword overlap score
  const queryTerms = query.toLowerCase().split(' ');
  const contentTerms = result.content.toLowerCase().split(' ');
  const matchingTerms = queryTerms.filter(term => contentTerms.includes(term));
  const keywordScore = matchingTerms.length / queryTerms.length;

  // Calculate position score
  let positionScore = 0;
  for (const term of queryTerms) {
    const pos = result.content.toLowerCase().indexOf(term.toLowerCase());
    if (pos >= 0) {
      // Higher score if term appears earlier
      positionScore += 1.0 - (pos / result.content.length);
    }
  }
  positionScore = positionScore / queryTerms.length;

  // Combined relevance score
  const relevanceScore = (
    0.6 * result.similarity +
    0.3 * keywordScore +
    0.1 * positionScore
  );

  return {
    ...result,
    keywordScore,
    positionScore,
    relevanceScore
  };
});

// Sort by relevance score
results.sort((a, b) => b.relevanceScore - a.relevanceScore);

// Limit to top results
const topResults = results.slice(0, 5);

// Format context for prompt
const formattedContext = topResults.map((result, index) => {
  return `[Source ${index + 1}: ${result.metadata.source || 'Unknown'}]\n${result.content}\n`;
}).join('\n');

return {
  json: {
    ...searchResults,
    query,
    ranked_results: topResults,
    formatted_context: formattedContext
  }
};

// Prompt construction
const query = $input.item.json.query;
const context = $input.item.json.formatted_context;

// Legal domain prompt template
const promptTemplate = `
You are a legal research assistant. Use ONLY the provided context to answer the question.
Do not use outside knowledge.
If the context does not contain enough information, respond exactly with: "Not found in context."

Context:
${context}

Question: ${query}

Instructions for your answer:
- Provide the response in clear bullet points.
- Each bullet point must end with the citation of the supporting source (e.g., [Source 3]).
- Do not repeat irrelevant context.
- Do not speculate outside the provided context.
- Do not say "based on the context" or similar phrases - just answer directly.
- If you can't answer from the context, just say "Not found in context."

Answer:
`;

return {
  json: {
    ...($input.item.json),
    prompt: promptTemplate
  }
};

// Response validation
const response = $input.item.json.message.content;
const query = $input.item.json.query;
const context = $input.item.json.formatted_context;
const rankedResults = $input.item.json.ranked_results;

// Calculate confidence score
let confidenceScore = 0.8; // Default confidence

// Check response length
if (response.length < 10) {
  confidenceScore *= 0.5;
}

// Check for "Not found in context"
if (response.includes("Not found in context")) {
  confidenceScore = 0.1;
}

// Check source support
const contextText = rankedResults.map(r => r.content).join(' ');
const responseLines = response.split('\n').filter(line => line.trim().length > 0);

// Count supported lines
let supportedLines = 0;
for (const line of responseLines) {
  // Skip very short lines
  if (line.length < 15) continue;

  // Check if key parts of the line appear in context
  const words = line.toLowerCase().split(' ');
  const keyWords = words.filter(w => w.length > 4 && !['about', 'would', 'should', 'could'].includes(w));

  if (keyWords.length > 0) {
    const matches = keyWords.filter(word => contextText.toLowerCase().includes(word));
    const supportScore = matches.length / keyWords.length;

    if (supportScore >= 0.5) {
      supportedLines++;
    }
  }
}

// Calculate source support score
const sourceSupport = responseLines.length > 0 ? supportedLines / responseLines.length : 0;

// Calculate query relevance
const queryTerms = query.toLowerCase().split(' ');
const responseTerms = response.toLowerCase().split(' ');
const queryOverlap = queryTerms.filter(term => responseTerms.includes(term)).length / queryTerms.length;

if (queryOverlap < 0.3) {
  confidenceScore *= 0.8;
}

// Final confidence calculation
confidenceScore = confidenceScore * (0.7 + 0.3 * sourceSupport);

// Extract citations
const citationRegex = /\[Source (\d+)\]/g;
let match;
const citations = [];

while ((match = citationRegex.exec(response)) !== null) {
  const sourceNum = parseInt(match[1]) - 1;
  if (sourceNum >= 0 && sourceNum < rankedResults.length) {
    citations.push({
      text: response.substring(Math.max(0, match.index - 50), match.index + match[0].length),
      source: rankedResults[sourceNum].metadata.source || 'Unknown',
      sourceIndex: sourceNum
    });
  }
}

// Cache the result for future queries
// In a real implementation, this would store in Redis

return {
  json: {
    query_id: $input.item.json.query_id,
    query: query,
    response: response,
    confidence_score: confidenceScore,
    citations: citations,
    context_used: rankedResults.map(r => ({
      content: r.content,
      metadata: r.metadata,
      relevance: r.relevanceScore
    })),
    processing_time: (Date.now() - new Date($input.item.json.timestamp).getTime()) / 1000
  }
};

// Analytics logging function
async function logAnalytics(items) {
  const item = items[0];

  // Extract key metrics
  const {
    query_id,
    query,
    confidence_score,
    processing_time,
    context_used
  } = item.json;

  // In a real implementation, this would log to a database
  console.log(`Analytics for query ${query_id}:`);
  console.log(`- Query: ${query}`);
  console.log(`- Confidence: ${confidence_score}`);
  console.log(`- Processing time: ${processing_time}s`);
  console.log(`- Context chunks used: ${context_used.length}`);

  // Return the items unchanged
  return items;
}
